import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'

export const namespaced = true

export const state = () => ({
  views: [],
  currentView: {},
  lastView: null,
  // ADDED: Track which project's views are loaded
  loadedProjectId: null
})

export const getters = getterTree(state, {
  viewNames: state => state.views.map(v => v.name),
  hasViews: state => state.views.length > 0,
  currentViewName: state => state.currentView?.name || null,
  // ADDED: Get views for active project only
  projectViews: state => {
    const projectId = $storex.projects?.activeProject?.project_id
    return projectId ? state.views.filter(v => v.project_id === projectId) : []
  },
  // ADDED: Check if views are loaded for current project
  viewsLoaded: state => {
    const projectId = $storex.projects?.activeProject?.project_id
    return state.loadedProjectId === projectId
  }
})

export const mutations = mutationTree(state, {
  setViews(state, views) {
    state.views = views || []
  },
  setCurrentView(state, view) {
    state.currentView = view || {}
  },
  setLastView(state, view) {
    state.lastView = view || null
  },
  addView(state, view) {
    if (!state.views.find(v => v.name === view.name && v.project_id === view.project_id)) {
      state.views.push(view)
    }
  },
  updateView(state, view) {
    const index = state.views.findIndex(v => v.name === view.name && v.project_id === view.project_id)
    if (index >= 0) {
      state.views[index] = view
    }
  },
  removeView(state, { viewName, projectId }) {
    state.views = state.views.filter(v => !(v.name === viewName && v.project_id === projectId))
  },
  // ADDED: Track loaded project
  setLoadedProjectId(state, projectId) {
    state.loadedProjectId = projectId
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
      await $storex.views.loadViews()
    },

    async loadViews() {
      try {
        const views = await API.views.list()
        $storex.views.setViews(views || [])
      } catch (error) {
        console.error('Failed to load views:', error)
        $storex.views.setViews([])
      }
    },

    // ADDED: Get or create last view for active project
    async getProjectLastView() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (!projectId) return null

        const projectViews = state.views.filter(v => v.project_id === projectId)
        if (projectViews.length === 0) {
          return null
        }

        // Return the most recently updated view
        return projectViews.reduce((latest, current) => 
          (current.last_update || 0) > (latest.last_update || 0) ? current : latest
        )
      } catch (error) {
        console.error('Failed to get project last view:', error)
        return null
      }
    },

    async saveView(_, viewName) {
      try {
        const layout = $storex.ui._desktopApi?.toJSON()
        if (!layout) {
          throw new Error('No layout to save')
        }
        const projectId = $storex.projects?.activeProject?.project_id
        const view = {
          name: viewName,
          layout: layout,
          project_id: projectId,
          last_update: Date.now()
        }
        await API.views.save(view)
        $storex.views.addView(view)
        $storex.views.setLastView(view)
      } catch (error) {
        console.error('Failed to save view:', error)
        throw error
      }
    },

    // ADDED: Auto-save current view with updated layout
    async autoSaveCurrentView() {
      try {
        const view = state.lastView || state.currentView
        if (!view?.name) return

        const layout = $storex.ui._desktopApi?.toJSON()
        if (!layout) return

        const projectId = $storex.projects?.activeProject?.project_id
        const updatedView = {
          ...view,
          layout: layout,
          project_id: projectId,
          last_update: Date.now()
        }
        await API.views.save(updatedView)
        $storex.views.updateView(updatedView)
        $storex.views.setLastView(updatedView)
      } catch (error) {
        console.error('Failed to auto-save view:', error)
      }
    },

    async loadView(_, view) {
      try {
        $storex.views.setCurrentView(view)
        $storex.views.setLastView(view)
        if (view.layout && $storex.ui._desktopApi) {
          $storex.ui._desktopApi.fromJSON(view.layout)
        }
      } catch (error) {
        console.error('Failed to load view:', error)
        throw error
      }
    },

    async deleteView(_, { viewName, projectId }) {
      try {
        await API.views.delete(viewName)
        $storex.views.removeView({ viewName, projectId })
        if (state.currentView?.name === viewName) {
          $storex.views.setCurrentView({})
        }
      } catch (error) {
        console.error('Failed to delete view:', error)
        throw error
      }
    },

    async renameView(_, { oldName, newName }) {
      try {
        await API.views.rename(oldName, newName)
        const view = state.views.find(v => v.name === oldName)
        if (view) {
          view.name = newName
          $storex.views.updateView(view)
          if (state.currentView?.name === oldName) {
            $storex.views.setCurrentView(view)
          }
          if (state.lastView?.name === oldName) {
            $storex.views.setLastView(view)
          }
        }
      } catch (error) {
        console.error('Failed to rename view:', error)
        throw error
      }
    },

    // CHANGED: Load views for active project and create default if none exist
    async loadViewsForActiveProject() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (!projectId) {
          $storex.views.setViews([])
          return
        }

        // Load all views
        await $storex.views.loadViews()

        // Filter to active project's views
        const projectViews = state.views.filter(v => v.project_id === projectId)

        // If no views exist, create a default empty grid view
        if (projectViews.length === 0) {
          await $storex.views.createDefaultView()
        } else {
          // Load the most recent view
          const lastView = await $storex.views.getProjectLastView()
          if (lastView) {
            await $storex.views.loadView(lastView)
          }
        }

        // Mark this project as loaded
        $storex.views.setLoadedProjectId(projectId)
      } catch (error) {
        console.error('Failed to load views for active project:', error)
      }
    },

    // ADDED: Create a default empty grid view for the project
    async createDefaultView() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (!projectId) return

        // Create a basic empty layout
        const defaultLayout = {
          panels: [],
          layout: {
            type: 'branch',
            size: 1,
            data: [],
            children: []
          }
        }

        const view = {
          name: `Default View - ${new Date().toLocaleDateString()}`,
          layout: defaultLayout,
          project_id: projectId,
          last_update: Date.now()
        }

        await API.views.save(view)
        $storex.views.addView(view)
        $storex.views.setLastView(view)
        await $storex.views.loadView(view)
      } catch (error) {
        console.error('Failed to create default view:', error)
      }
    }
  }
)

async setActiveProject ({ state }, project) {
  const { project_id, project_name, codx_path } = project
  if (!codx_path) {
    project = $storex.projects.allProjects
      .find(p => p.project_name === project_name || 
                p.project_id === project_id)
  }
  if (project?.codx_path === state.activeProject?.codx_path) {
    return
  }

  if (project?.codx_path) {
    state.projectLoading = true
    const projectName = project.project_name

    $storex.ui.setProjectLoadingState({ 
      isLoading: true, 
      projectName
    })

    try {
      const overlay = document.querySelector('[data-test="project-loading-overlay"]')?.__vue__?.proxy
      overlay?.markStepLoading('fetch')

      API.setActiveProject(project)
      overlay?.completeStep('fetch', 'Settings loaded')

      overlay?.markStepLoading('settings')
      const existsProject = state.allProjects.find(p => p.project_id === API.activeProject.project_id)
      if (!existsProject) {
        await $storex.projects.setAllProjects([...state.allProjects, API.activeProject])
      }
      state.activeProject = state.allProjectsById[API.activeProject.project_id]
                            || state.allProjects.find(p => p.project_name === 'codx-junior')
      overlay?.completeStep('settings', 'Config ready')

      overlay?.markStepLoading('models')
      const models = await API.projects.ai.models.list()
      state.ai = { ...state.activeProject.$state.ai, models }
      overlay?.completeStep('models', `${models.length} models loaded`)

      overlay?.markStepLoading('chats')
      await $storex.chats.loadChats()
      if ($storex.chats.activeChat?.project_id !== API.activeProject.project_id) {
        $storex.chats.clearActiveChat()
      }
      overlay?.completeStep('chats', 'Chats loaded')

      // ADDED: Load views for the active project
      overlay?.markStepLoading('views')
      await $storex.views.loadViewsForActiveProject()
      overlay?.completeStep('views', 'Views loaded')

      $storex.projects.addRecentProject(state.activeProject)
      state.workspaces = API.workspaces
      $storex.ui.saveState()

      overlay?.completeStep('finalize', 'Ready')
      overlay?.finishLoading()

    } catch(ex) {
      console.error("Error setting active project", ex)
      const overlay = document.querySelector('[data-test="project-loading-overlay"]')?.__vue__?.proxy
      overlay?.markStepError('finalize', ex.message)
      overlay?.setError(`Failed to load project: ${ex.message}`)
      $storex.ui.setProjectLoadingError(ex.message)
    } finally {
      state.projectLoading = false
      setTimeout(() => {
        $storex.ui.setProjectLoadingState({ isLoading: false })
      }, 500)
    }
  }
},

export const state = () => ({
  // ... existing state ...
  viewEditor: null,
  // ADDED: Track last loaded project for view association
  lastLoadedProjectId: null,
  // ... rest of state ...
})

