## File 3: src/api/modules/views.js

**No changes needed** – views module already supports project context through API instance.

```js src/api/modules/views.js
/**
 * Views API module
 * Handles view operations: list, save, delete, rename
 * Each project's API instance calls these methods with project context
 */

export const viewsModule = (API) => ({
  list() {
    return API.get('/api/views')
  },

  save(view) {
    return API.post('/api/views', view)
  },

  delete(name) {
    return API.delete(`/api/views/${encodeURIComponent(name)}`)
  },

  rename(oldName, newName) {
    return API.put(`/api/views/${encodeURIComponent(oldName)}`, { name: newName })
  }
})
```

