  floatingCodxJunior: false,
  notifications: [],
  noVNCSettings: {
    resize: 'remote',
  },
  theme: 'dark',
  activeTab: 'home',
  newProject: false,
  activeApp: null,
  appShowMode: null,
  _desktopApi: null,
  viewEditor: null,
  activeTeam: null,
  teamBarCollapsed: false,
  panelWidths: {
    chat: 30,
    changes: 33,
    preview: 37
  },
  projectLoadingState: {
    isLoading: false,
    projectName: '',
    currentStep: null,
    error: null
  }
})

export const getters = getterTree(state, {
  isLandscape: state => state.orientation !== 'portrait',
  monitorToken: state => state.monitors[state.monitor],
  isSharedScreen: () => window.location.pathname === '/shared',
  enableFileManger: () => API.globalSettings?.enable_file_manager,
  activeApps: () => Object.values($storex.ui.openApps),
  isVibeMode: state => state.viewMode === 'vibe',
  isExpertMode: state => state.viewMode === 'expert',
})

export const mutations = mutationTree(state, {
  setActiveTab(state, tab) {
    tab = tab || 'home'
    if (tab !== 'home') {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    } else {
      state.activeTab = null
      state.activeApp = null
    }
    $storex.ui.saveState()
  },
  showTab(state, tab) {
    if (tab !== state.activeTab) {
      $storex.ui.setActiveTab(tab)
    }
    if (!state.isMobile) {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    }
  },
  closeTab(state) {
    state.activeTab = null
  },
  setCodxJuniorWidth(state, width) {
    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Logs',
      component: 'log-viewer'
    })
  },
  openChatLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Chat logs',
      component: 'chat-logs'
    })
  },
  setVoiceLanguage(state, voiceLanguage) {
    state.voiceLanguage = voiceLanguage
    $storex.ui.saveState()
  },
  setVibeMode(state) {
    state.viewMode = 'vibe'
    $storex.ui.saveState()
  },
  setExpertMode(state) {
    state.viewMode = 'expert'
    $storex.ui.saveState()
  },
  setViewMode(state, mode) {
    state.viewMode = mode
    $storex.ui.saveState()
  },
  setAppDivided(state, divided) {
    state.appDivided = divided
    $storex.ui.saveState()
  },
  setMonitor(state, monitor) {
    state.monitor = monitor
    $storex.ui.saveState()
  },
  setColorsMap(state, colorsMap) {
    state.colorsMap = colorsMap
    $storex.ui.saveState()
  },
  coderOpenPath(state, project) {
    state.coderProjectCodxPath = project.codx_path
  },
  setUIready(state) {
    $storex.ui.loadState()
    state.uiReady = true
  },
  setFloatinCodxJunior(state, floating) {
    state.floatingCodxJunior = floating
    $storex.ui.saveState()
  },
  toggleFloatinCodxJunior(state) {
    state.floatingCodxJunior = !state.floatingCodxJunior
    $storex.ui.saveState()
  },
  addNotification(state, { text, type }) {
    const existing = state.notifications?.find(n => n.text === text)
    if (existing) {
      existing.ts = moment().format("HH:mm:ss")
      return
    }
    const notif = {
      ts: moment().format("HH:mm:ss"),
      text,
      type: type || 'info'
    }
    state.notifications.push(notif)
    setTimeout(() => $storex.ui.removeNotification(notif), 30000)
  },
  removeNotification(state, notification) {
    state.notifications.splice(
      state.notifications.findIndex(n => n === notification), 1)
  },
  clearNotifications(state, notifications) {
    state.notifications = state.notifications.filter(n => !notifications.includes(n))
  },
  setNoVNCSettings(state, settings) {
    state.noVNCSettings = { ...state.noVNCSettings, ...settings }
  },
  setTheme(state, theme) {
    state.theme = theme
  },
  showNewProject(state, show) {
    state.newProject = show
  },
  cloneApp(state, app) {
    $storex.ui.showApp({ ...app, tabId: null })
  },
  showApp(state, app) {
    // Check if panel already exists and activate it
    if (state._desktopApi && app.params?.chat?.id) {
      const existingPanel = state._desktopApi.panels
          .find(({ _params }) => _params?.chat?.id === app.params?.chat?.id
      )
      if (existingPanel) {
        existingPanel.api.setActive()
        state.activeApp = app
        return
      }
    }

    app.tabId = app.tabId || `${app.key || app.name}-${Date.now()}`
    app.params = app.params || {}
    app.openedAt = Date.now()
    if (state.viewMode !== 'vibe') {
      state.openApps = {
        ...state.openApps,
        [app.tabId]: app
      }
    }
    state.activeApp = app
  },
  updateAppParams(state, { tabId, params }) {
    const app = state.openApps[tabId]
    if (!app) return
    state.openApps = {
      ...state.openApps,
      [tabId]: {
        ...app,
        params: {
          ...app.params,
          ...params
        }
      }
    }
  },
  closeApp(state, app) {
    if (!app) return
    delete state.openApps[app.tabId]
    if (state.activeApp?.tabId === app.tabId) {
      const remainingApps = Object.values(state.openApps)
      if (remainingApps.length > 0) {
        state.activeApp = remainingApps.reduce((latest, current) =>
          current.openedAt > latest.openedAt ? current : latest
        )
      } else {
        state.activeApp = null
      }
    }
    if (!Object.keys(state.openApps).length) {
      if (!state.activeTab) {
        $storex.ui.showTab(state.lastActiveTab || 'tasks')
      }
    }
    $storex.ui.saveState()
  },
  setAppShowMode(state, mode) {
    state.appShowMode = mode
  },
  openChat(_, chat) {
    $storex.ui.showApp({
      name: chat.name,
      component: 'chat',
      params: {
        chat: {
          id: chat.id,
          name: chat.name,
          owner_project_id: chat.owner_project_id
        }
      }
    })
  },
  openFileInViewer(_, filePath) {
    const fileName = filePath.split('/').pop()
    $storex.ui.showApp({
      key: `file-viewer-${filePath}`,
      name: fileName,
      component: 'file-viewer',
      params: { filePath }
    })
  },
  setDesktopApi(state, api) {
    state._desktopApi = api
  },
  openViewEditor(state, view = null) {
    state.viewEditor = { view: view || null }
  },
  closeViewEditor(state) {
    state.viewEditor = null
  },
  setActiveTeam(state, team) {
    state.activeTeam = team
    $storex.ui.saveState()
  },
  setTeamBarCollapsed(state, collapsed) {
    state.teamBarCollapsed = collapsed
    $storex.ui.saveState()
  },
  setPanelWidth(state, { panel, width }) {
    state.panelWidths = {
      ...state.panelWidths,
      [panel]: width
    }
    $storex.ui.saveState()
  },
  setProjectLoadingState(state, loadingState) {
    state.projectLoadingState = {
      ...state.projectLoadingState,
      ...loadingState
    }
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }, $storex) {
      $storex.ui.handleResize()
      window.addEventListener('resize', () => $storex.ui.handleResize())
      if (API.user?.theme) {
        state.theme = API.user.theme
      }
      state.coderProjectCodxPath = null
    },
    saveState({ state }) {
      if (!state.uiReady) {
        return
      }
      const data = { 
        ...state, 
        uiReady: false,
        openApps: {},
        _desktopApi: null,
        viewEditor: null,
        projectLoadingState: {
          isLoading: false,
          projectName: '',
          currentStep: null,
          error: null
        }
      }
      localStorage.setItem('uiState', JSON.stringify(data))
    },
    async loadState({ state }) {
      const savedState = localStorage.getItem('uiState')
      if (savedState) {
        const parsedState = JSON.parse(savedState)
        Object.keys(parsedState)
          .forEach(k => state[k] = parsedState[k])
      }
      const {
        activeProject: project_id,
        activeChat: chatId
      } = state

      if (project_id && project_id !== $storex.projects.activeProject?.project_id) {
        await $storex.projects.activeProjectChanged({ project_id })
      }
      if (chatId && $storex.projects.activeProject) {
        $storex.projects.setActiveChat({ id: chatId })
      }

      $storex.ui.handleResize()
    },
    handleResize({ state }) {
      const width = window.innerWidth
      const height = window.innerHeight
      const isMobile = width <= 1024
      const orientation = width > height ? 'landscape' : 'portrait'
      state.isMobile = isMobile
      state.orientation = orientation  
    },
    loadTask (_, task) {
      $storex.projects.setActiveChat(task)
    },
    async openFile({ state }, file) {
      if (state.isMobile) {
        state.openedFile = file
      } else {
        await API.coder.openFile(file)
      }
      state.showCoder = true
    },
    async openProjectFile({ state }, file) {
      const { project_path } = $storex.projects.activeProject
      if (!file.startsWith(project_path)) {
        if (!file.startsWith("/") && !project_path.endsWith("/")) {
          file = "/" + file
        }
        file = project_path + file
      }
      await API.coder.openFile(file)
      state.showCoder = true
    },
    setScreenResolution(_, resolution) {
      API.screen.setScreenResolution(resolution)
    },
    async readScreenResolutions ({ state }) {
      await API.screen.getScreenResolution()
      state.resolution = API.screen.display?.resolution
      state.resolutions = API.screen.display?.resolutions
    },
    copyTextToClipboard(_, text) {
      const textArea = document.createElement('textarea')
      textArea.value = text
      document.body.appendChild(textArea)
      textArea.focus()
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      $storex.ui.addNotification({ text: "Text copied" })
    },
    async readClipboardText(_, itemType = "text/plain") {
      const items = await navigator.clipboard.read()
      const getText = async item => {
        const blob = await item.getType(itemType)
        return await blob.text()
      }
      const allTexts = await Promise.all(
                        items.filter(i => i.types.includes(itemType))
                              .map(i => getText(i)))
      return allTexts.reduce((a, b) => a + b, "")
    },
    async shareScreen() {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        preferCurrentTab: true,
      })
      const [track] = stream.getVideoTracks()
    },
    openNewWindowAppPanel(_, app) {
      const { origin } = window.location
      const url = `${origin}${app.path}`
      window.open(url, app.name)
    },

    // ── Team panel openers ────────────────────────────────────────────────────

    openTeamChannel(_, { team, channel }) {
      $storex.ui.showApp({
        key: `team-channel-${channel.id}`,
        name: `# ${channel.name}`,
        component: 'team-channel',
        params: { team, channel }
      })
    },

    async openTeamDM(_, { team, member }) {
      const chatId = await $storex.teams.openDirectMessage({ teamId: team.id, member })
      $storex.ui.showApp({
        key: `team-dm-${team.id}-${member.id}`,
        name: `@ ${member.username}`,
        component: 'team-dm',
        params: { team, member, chatId }
      })
    },

    openTeamMediaLibrary(_, { team }) {
      $storex.ui.showApp({
        key: `team-media-${team.id}`,
        name: `🖼 ${team.name} Media`,
        component: 'team-media-library',
        params: { team }
      })
    },

    // ── QuickBar app openers ──────────────────────────────────────────────────

    openVibeCoding() {
      $storex.ui.showApp({
        key: 'vibe-coding',
        name: 'Vibe Coding',
        component: 'vibe-coding',
        params: {}
      })
    },

    openProjects() {
      $storex.ui.showApp({
        key: 'projects',
        name: 'Projects',
        component: 'projects',
        params: {}
      })
    },

    openTeams() {
      $storex.ui.showApp({
        key: 'teams',
        name: 'Teams',
        component: 'teams',
        params: {}
      })
    },

    openWorkspaces() {
      $storex.ui.showApp({
        key: 'workspaces',
        name: 'Workspaces',
        component: 'workspaces',
        params: {}
      })
    },

    openTasks() {
      $storex.ui.setActiveTab('tasks')
    },

    openWiki() {
      $storex.ui.setActiveTab('wiki')
    },

    openMediaLibrary() {
      $storex.ui.showApp({
        key: 'media-library',
        name: 'Media Library',
        component: 'media-library',
        params: {}
      })
    },

    openHome() {
      $storex.ui.setActiveTab('home')
    },

    openTutorial(_, tutorialId) {
      $storex.ui.showApp({
        key: `tutorial-${tutorialId}`,
        name: 'Knowledge',
        component: 'knowledge',
        params: { tutorial: tutorialId }
      })
    },

    // --- Project loading state actions ---

    setProjectLoading(_, isLoading) {
      $storex.ui.setProjectLoadingState({ isLoading })
    },

    updateProjectLoadingStep(_, { stepId, status, options = {} }) {
      window.dispatchEvent(new CustomEvent('project-loading-step', {
        detail: { stepId, status, options }
      }))
    },

    setProjectLoadingError(_, error) {
      $storex.ui.setProjectLoadingState({ error })
    }
  },
)

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'

export const namespaced = true

export const state = () => ({
  views: [],
  currentView: {},
  lastView: null
})

export const getters = getterTree(state, {
  viewNames: state => state.views.map(v => v.name),
  hasViews: state => state.views.length > 0,
  currentViewName: state => state.currentView?.name || null,
  projectViews: state => {
    const projectId = $storex.projects?.activeProject?.project_id
    return projectId ? state.views.filter(v => v.project_id === projectId) : []
  }
})

export const mutations = mutationTree(state, {
  setViews(state, views) {
    state.views = views || []
  },
  setCurrentView(state, view) {
    state.currentView = view || {}
  },
  setLastView(state, view) {
    state.lastView = view || null
  },
  addView(state, view) {
    if (!state.views.find(v => v.name === view.name && v.project_id === view.project_id)) {
      state.views.push(view)
    }
  },
  updateView(state, view) {
    const index = state.views.findIndex(v => v.name === view.name && v.project_id === view.project_id)
    if (index >= 0) {
      state.views[index] = view
    }
  },
  removeView(state, { viewName, projectId }) {
    state.views = state.views.filter(v => !(v.name === viewName && v.project_id === projectId))
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
      await $storex.views.loadViews()

      $storex.store.subscribe((mutation, state) => {
        if (mutation.type === 'projects/setActiveProject') {
          $storex.views.onActiveProjectChanged()
        }
      })
    },

    async loadViews() {
      try {
        const api = $storex.projects?.activeProject?.$api || API
        const views = await api.views.list()
        $storex.views.setViews(views || [])
      } catch (error) {
        console.error('Failed to load views:', error)
        $storex.views.setViews([])
      }
    },

    async onActiveProjectChanged() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (!projectId) {
          $storex.views.setCurrentView({})
          $storex.views.setLastView(null)
          return
        }

        await $storex.views.loadViews()

        const projectViews = state.views.filter(v => v.project_id === projectId)

        if (projectViews.length === 0) {
          await $storex.views.createDefaultView()
        } else {
          const lastView = await $storex.views.getProjectLastView()
          if (lastView) {
            await $storex.views.loadView(lastView)
          }
        }
      } catch (error) {
        console.error('Failed to handle active project change:', error)
      }
    },

    async getProjectLastView() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (!projectId) return null

        const projectViews = state.views.filter(v => v.project_id === projectId)
        if (projectViews.length === 0) {
          return null
        }

        return projectViews.reduce((latest, current) => 
          (current.last_update || 0) > (latest.last_update || 0) ? current : latest
        )
      } catch (error) {
        console.error('Failed to get project last view:', error)
        return null
      }
    },

    async saveView(_, viewName) {
      try {
        const layout = $storex.ui._desktopApi?.toJSON()
        if (!layout) {
          throw new Error('No layout to save')
        }
        const projectId = $storex.projects?.activeProject?.project_id
        const api = $storex.projects?.activeProject?.$api || API

        const view = {
          name: viewName,
          layout: layout,
          project_id: projectId,
          last_update: Date.now()
        }

        await api.views.save(view)
        $storex.views.addView(view)
        $storex.views.setLastView(view)
      } catch (error) {
        console.error('Failed to save view:', error)
        throw error
      }
    },

    async autoSaveCurrentView() {
      try {
        const view = state.lastView || state.currentView
        if (!view?.name) return

        const layout = $storex.ui._desktopApi?.toJSON()
        if (!layout) return

        const projectId = $storex.projects?.activeProject?.project_id
        const api = $storex.projects?.activeProject?.$api || API

        const updatedView = {
          ...view,
          layout: layout,
          project_id: projectId,
          last_update: Date.now()
        }

        await api.views.save(updatedView)
        $storex.views.updateView(updatedView)
        $storex.views.setLastView(updatedView)
      } catch (error) {
        console.error('Failed to auto-save view:', error)
      }
    },

    async loadView(_, view) {
      try {
        $storex.views.setCurrentView(view)
        $storex.views.setLastView(view)
        if (view.layout && $storex.ui._desktopApi) {
          $storex.ui._desktopApi.fromJSON(view.layout)
        }
      } catch (error) {
        console.error('Failed to load view:', error)
        throw error
      }
    },

    async deleteView(_, { viewName, projectId }) {
      try {
        const api = $storex.projects?.activeProject?.$api || API

        await api.views.delete(viewName)
        $storex.views.removeView({ viewName, projectId })
        if (state.currentView?.name === viewName) {
          $storex.views.setCurrentView({})
        }
      } catch (error) {
        console.error('Failed to delete view:', error)
        throw error
      }
    },

    async renameView(_, { oldName, newName }) {
      try {
        const api = $storex.projects?.activeProject?.$api || API

        await api.views.rename(oldName, newName)
        const view = state.views.find(v => v.name === oldName)
        if (view) {
          view.name = newName
          $storex.views.updateView(view)
          if (state.currentView?.name === oldName) {
            $storex.views.setCurrentView(view)
          }
          if (state.lastView?.name === oldName) {
            $storex.views.setLastView(view)
          }
        }
      } catch (error) {
        console.error('Failed to rename view:', error)
        throw error
      }
    },

    async createDefaultView() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        const api = $storex.projects?.activeProject?.$api || API

        if (!projectId) return

        const defaultLayout = {
          panels: [],
          layout: {
            type: 'branch',
            size: 1,
            data: [],
            children: []
          }
        }

        const view = {
          name: `Default View - ${new Date().toLocaleDateString()}`,
          layout: defaultLayout,
          project_id: projectId,
          last_update: Date.now()
        }

        await api.views.save(view)
        $storex.views.addView(view)
        $storex.views.setLastView(view)
        await $storex.views.loadView(view)
      } catch (error) {
        console.error('Failed to create default view:', error)
      }
    }
  }
)
